INSERT INTO patterns (id, name, blurb) VALUES
  ('public-rails', 'Public rails', 'Build open, shared infrastructure once, and let any firm compete on top of it.'),
  ('open-standard', 'Give away the standard', 'Publish a common standard anyone can build to; its value grows with every adopter.'),
  ('assembly-line', 'Assembly-line expertise', 'Break expert work into standard steps so scarce specialists spend their time only where they are needed.'),
  ('frugal', 'Frugal by design', 'Rethink the whole thing for people who cannot pay rich-world prices, rather than stripping down an expensive version.'),
  ('built-for-here', 'Built for local conditions', 'Design for the heat, dust, distances and budgets actually found here, instead of importing a design made for elsewhere.'),
  ('owned-by-members', 'Owned by its members', 'Pool many small producers so they gain scale and bargaining power while keeping ownership.');
